def verdict(side, cases):
    style = [c for c in cases if c[0].startswith("style:")]
    plain = [c for c in cases if not c[0].startswith("style:")]
    if not cases:
        return "harness produced no cases"
    if side == "after":
        bad = [c[0] for c in cases if not c[1]]
        return "failed %s" % bad if bad else None
    bad = [c[0] for c in plain if not c[1]]
    if bad:
        return "before fails behaviour %s" % bad
    if all(c[1] for c in style):
        return "before passes every style case"
    return None


def read(root, *parts):
    with open(os.path.join(root, *parts)) as handle:
        return handle.read()


def check(root, prelude, stem, side):
    solution = read(root, side, stem + ".py")
    harness = prelude + "\n\n\n" + read(root, "harnesses", stem + ".py")
    namespace = {"__name__": "solution"}
    try:
        with contextlib.redirect_stdout(io.StringIO()):
            exec(compile(solution, "solution.py", "exec"), namespace)
            namespace["__source__"] = solution
            exec(compile(harness, "harness.py", "exec"), namespace)
    except Exception as error:
        return "raised %s: %s" % (type(error).__name__, error)
    cases = [(label, expected == actual) for label, expected, actual in namespace.get("__results__", [])]
    return verdict(side, cases)


def main():
    root = os.path.dirname(os.path.abspath(__file__))
    prelude = read(root, "prelude.py").rstrip()
    stems = sys.argv[1:] or STEMS
    failures = 0
    for stem in stems:
        for side in ("before", "after"):
            why = check(root, prelude, stem, side)
            if why:
                failures += 1
                print("FAIL %s [%s] %s" % (stem, side, why))
    print("%d Python refactoring drills checked, %d failures" % (len(stems), failures))
    sys.exit(1 if failures else 0)


main()
